/* Lot 108: width, max-width and min-height on the box scrollers of the reader (generated by scripts/lot108_gen.py; expectations from scripts/lot108_model.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_sitecss.h"

static wf_site_t g_d;
static char g_html[4096];
static char g_o[1024];

static void prep(const char *css) {
    snprintf(g_html, sizeof(g_html), "<html><head><style>%s</style></head><body>"
             "<div id=o><div id=b><p id=i>i</p><p id=r>r</p></div></div><p id=q>q</p></body></html>", css);
    TEST_ASSERT_EQUAL(0, wf_site_prepare_ext(&g_d, g_html, (int)strlen(g_html), 640, 480, 0, 0));
    TEST_ASSERT_EQUAL(8, g_d.nnodes);
}

static const char *style_of(const char *id) {
    int i;
    g_o[0] = 0;
    for (i = 0; i < g_d.nnodes; i++)
        if (!strcmp(g_d.node[i].id, id)) wf_site_style_attr(&g_d, g_d.node[i].start, g_o, (int)sizeof(g_o));
    return g_o;
}

/* overflow-x, overflow-y, the absolute height, max-height, width,
 * max-width and min-height kept (px + 1), scr, the font size */
static const char *sc_of(int k) {
    const wf_site_node_t *n = &g_d.node[k];
    snprintf(g_o, sizeof(g_o), "%d %d %d %d %d %d %d %d %d", n->ov[0], n->ov[1], n->hpx, n->mpx, n->xpx[0],
             n->xpx[1], n->xpx[2], n->scr, g_d.fs[k]);
    return g_o;
}

static void test_l108_width_0(void) {
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } #b { min-height: 81%; height: --x; overflow-y: scroll } #o { max-width: calc(2em - 4px); width: 0.001em !important; overflow: visible scroll; width: 1in; height: 24.90vmax }  #i { animation: k 1s linear; animation-timeline: scroll(nearest inline) }");
    TEST_ASSERT_EQUAL(5, wf_site_box_scroller(&g_d, 3));
    TEST_ASSERT_EQUAL_STRING("1 5 0 0 0 0 0 0 16000", sc_of(3));
    TEST_ASSERT_EQUAL_STRING("", style_of("o"));
    TEST_ASSERT_EQUAL(5, wf_site_box_scroller(&g_d, 4));
    TEST_ASSERT_EQUAL_STRING("0 5 0 0 0 0 0 1 16000", sc_of(4));
    TEST_ASSERT_EQUAL_STRING("", style_of("b"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } #o { width: 1.25rem; height: 100px; max-width: min(10px, 2em, 3rem, 4vh) !important; overflow-x: scroll; min-height: calc() } div { overflow: auto hidden; min-height: initial; max-width: max(10%, 2em); height: 91%; width: 99.99% } #b { max-width: clamp(10px, 5em, 50px); min-height: 40000%; min-height: 41px; overflow: visible scroll } #o { font-size: 24px } #i { animation: k 1s linear; animation-timeline: scroll(nearest block) }");
    TEST_ASSERT_EQUAL(2, wf_site_box_scroller(&g_d, 3));
    TEST_ASSERT_EQUAL_STRING("5 2 101 0 0 0 0 0 24000", sc_of(3));
    TEST_ASSERT_EQUAL_STRING(" style=\"font-size:24px\"", style_of("o"));
    TEST_ASSERT_EQUAL(5, wf_site_box_scroller(&g_d, 4));
    TEST_ASSERT_EQUAL_STRING("1 5 0 0 0 0 42 1 24000", sc_of(4));
    TEST_ASSERT_EQUAL_STRING(" style=\"overflow-y:scroll;height:91%;min-height:41px;overflow-x:auto;width:99%;max-width:50px\"", style_of("b"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } #b { overflow: auto hidden } #o { overflow-y: auto; overflow: visible scroll; max-width: initial } #b { font-size: 12px } #i { animation: k 1s linear; animation-timeline: scroll(nearest inline) }");
    TEST_ASSERT_EQUAL(5, wf_site_box_scroller(&g_d, 3));
    TEST_ASSERT_EQUAL_STRING("1 5 0 0 0 0 0 0 16000", sc_of(3));
    TEST_ASSERT_EQUAL_STRING("", style_of("o"));
    TEST_ASSERT_EQUAL(2, wf_site_box_scroller(&g_d, 4));
    TEST_ASSERT_EQUAL_STRING("4 2 0 0 0 0 0 1 12000", sc_of(4));
    TEST_ASSERT_EQUAL_STRING(" style=\"font-size:12px\"", style_of("b"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } #o { width: 19vh; overflow-x: clip; overflow: clip; max-width: 0.5em } #b { width: 0.5in; overflow-x: hidden; max-width: 541px !important } #o { font-size: 24px } #i { animation: k 1s linear; animation-timeline: scroll(nearest inline) }");
    TEST_ASSERT_EQUAL(0, wf_site_box_scroller(&g_d, 3));
    TEST_ASSERT_EQUAL_STRING("3 3 0 0 0 0 0 0 24000", sc_of(3));
    TEST_ASSERT_EQUAL_STRING(" style=\"font-size:24px\"", style_of("o"));
    TEST_ASSERT_EQUAL(4, wf_site_box_scroller(&g_d, 4));
    TEST_ASSERT_EQUAL_STRING("2 0 0 0 49 542 0 1 24000", sc_of(4));
    TEST_ASSERT_EQUAL_STRING("", style_of("b"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } #b { height: +4em; overflow-x: auto; width: max-content } #o { overflow-x: auto; min-height: 20vh; max-height: 0.001em } div { overflow-x: auto; overflow-x: visible; max-height: 461px; min-height: 100vh }  #i { animation: k 1s linear; animation-timeline: scroll(nearest inline) }");
    TEST_ASSERT_EQUAL(4, wf_site_box_scroller(&g_d, 3));
    TEST_ASSERT_EQUAL_STRING("4 0 0 0 0 0 0 0 16000", sc_of(3));
    TEST_ASSERT_EQUAL_STRING("", style_of("o"));
    TEST_ASSERT_EQUAL(4, wf_site_box_scroller(&g_d, 4));
    TEST_ASSERT_EQUAL_STRING("4 0 0 462 0 0 0 1 16000", sc_of(4));
    TEST_ASSERT_EQUAL_STRING(" style=\"overflow-y:auto;height:64px;max-height:461px;min-height:480px\"", style_of("b"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } #b { width: 12.5px; overflow-y: visible; overflow-x: visible; min-height: 100vh } #o { width: 581px !important; overflow: auto hidden } div { max-height: 384px !important; width: 40000% !important; min-height: 250%; max-width: fit-content; overflow-x: scroll } html { font-size: 24px } #i { animation: k 1s linear; animation-timeline: scroll(nearest inline) }");
    TEST_ASSERT_EQUAL(2, wf_site_box_scroller(&g_d, 3));
    TEST_ASSERT_EQUAL_STRING("4 2 0 385 582 0 0 1 24000", sc_of(3));
    TEST_ASSERT_EQUAL_STRING(" style=\"overflow-x:auto;width:581px\"", style_of("o"));
    TEST_ASSERT_EQUAL(0, wf_site_box_scroller(&g_d, 4));
    TEST_ASSERT_EQUAL_STRING("1 1 0 385 0 0 0 0 24000", sc_of(4));
    TEST_ASSERT_EQUAL_STRING("", style_of("b"));
}

